# ========================
# SOLUTION ALTERNATIVE POUR LES EMAILS (SMTP DIRECT)
# ========================
import smtplib
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from email.header import Header
from email.utils import formataddr

class EmailService:
    """Service d'email utilisant SMTP direct sans Flask-Mail"""
    
    def __init__(self):
        self.smtp_server = 'smtp.gmail.com'
        self.smtp_port = 587
        self.sender_email = 'contact.fkcorporate@gmail.com'
        self.sender_name = 'FK Corporate Intelligence'
        self.password = os.environ.get('GMAIL_APP_PASSWORD', '')
        
        # Vérifier si les credentials sont disponibles
        if not self.password:
            print("⚠️ GMAIL_APP_PASSWORD non défini - emails en mode simulation")
            self.simulation_mode = True
        else:
            self.simulation_mode = False
            print(f"✅ Service email SMTP configuré ({self.sender_email})")
    
    def send_email(self, to_email, subject, body, html_body=None, cc=None, bcc=None):
        """Envoyer un email via SMTP direct"""
        
        # Mode simulation si pas de mot de passe
        if self.simulation_mode:
            print(f"📧 [SIMULATION] Email à: {to_email}")
            print(f"   Sujet: {subject}")
            print(f"   Contenu: {body[:100]}...")
            return True
        
        try:
            # Créer le message
            msg = MIMEMultipart('alternative')
            msg['Subject'] = subject
            msg['From'] = formataddr((str(Header(self.sender_name, 'utf-8')), self.sender_email))
            
            # Gérer les destinataires
            if isinstance(to_email, list):
                msg['To'] = ', '.join(to_email)
                recipients = to_email
            else:
                msg['To'] = to_email
                recipients = [to_email]
            
            # Ajouter CC si spécifié
            if cc:
                if isinstance(cc, list):
                    msg['Cc'] = ', '.join(cc)
                    recipients.extend(cc)
                else:
                    msg['Cc'] = cc
                    recipients.append(cc)
            
            # Ajouter BCC si spécifié
            if bcc:
                if isinstance(bcc, list):
                    recipients.extend(bcc)
                else:
                    recipients.append(bcc)
            
            # Partie texte
            text_part = MIMEText(body, 'plain', 'utf-8')
            msg.attach(text_part)
            
            # Partie HTML si fournie
            if html_body:
                html_part = MIMEText(html_body, 'html', 'utf-8')
                msg.attach(html_part)
            
            # Envoyer via SMTP
            with smtplib.SMTP(self.smtp_server, self.smtp_port) as server:
                server.starttls()
                server.login(self.sender_email, self.password)
                server.send_message(msg, from_addr=self.sender_email, to_addrs=recipients)
            
            print(f"✅ Email envoyé à {to_email}")
            return True
            
        except Exception as e:
            print(f"❌ Erreur envoi email à {to_email}: {e}")
            # Fallback en mode simulation
            print(f"📧 [FALLBACK SIMULATION] Email à: {to_email}")
            print(f"   Sujet: {subject}")
            return False
    
    def send_contact_confirmation(self, nom_complet, email, societe, telephone, sujet, message, reference):
        """Envoyer les emails pour une demande de contact"""
        
        # 1. Email à l'administrateur
        admin_subject = f"Nouvelle demande: {sujet[:50]}"
        admin_body = f"""
        NOUVELLE DEMANDE DE CONTACT
        
        Nom: {nom_complet}
        Email: {email}
        Société: {societe or 'Non spécifié'}
        Téléphone: {telephone or 'Non spécifié'}
        
        Sujet: {sujet}
        
        Message:
        {message}
        
        Référence: {reference}
        Date: {datetime.now().strftime('%d/%m/%Y %H:%M:%S')}
        """
        
        admin_sent = self.send_email(
            to_email='contact.fkcorporate@gmail.com',
            subject=admin_subject,
            body=admin_body
        )
        
        # 2. Email de confirmation au client
        client_subject = "Confirmation de votre demande"
        client_html = f"""
        <!DOCTYPE html>
        <html>
        <head>
            <meta charset="UTF-8">
            <style>
                body {{ font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; }}
                .header {{ background: #0A1929; color: white; padding: 30px; text-align: center; border-radius: 5px 5px 0 0; }}
                .content {{ padding: 30px; background: #f8f9fa; border-radius: 0 0 5px 5px; }}
                .info-box {{ background: white; padding: 20px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #0066CC; }}
            </style>
        </head>
        <body>
            <div class="header">
                <h1>FK Corporate Intelligence</h1>
                <p>Confirmation de votre demande</p>
            </div>
            <div class="content">
                <h2>Bonjour {nom_complet},</h2>
                <p>Nous avons bien reçu votre demande de démonstration.</p>
                <div class="info-box">
                    <p><strong>Référence :</strong> {reference}</p>
                    <p><strong>Sujet :</strong> {sujet}</p>
                    <p><strong>Date :</strong> {datetime.now().strftime('%d/%m/%Y à %H:%M')}</p>
                </div>
                <p>Notre équipe vous contactera dans les plus brefs délais pour organiser une démonstration personnalisée.</p>
                <p>Cordialement,<br><strong>L'équipe FK Corporate Intelligence</strong></p>
                <hr>
                <p style="font-size: 12px; color: #666;">
                    Cet email a été envoyé automatiquement. Merci de ne pas y répondre.<br>
                    FK Corporate Intelligence - contact.fkcorporate@gmail.com
                </p>
            </div>
        </body>
        </html>
        """
        
        client_body = f"""
        Confirmation de votre demande
        
        Bonjour {nom_complet},
        
        Nous avons bien reçu votre demande de démonstration.
        
        Référence : {reference}
        Sujet : {sujet}
        Date : {datetime.now().strftime('%d/%m/%Y à %H:%M')}
        
        Notre équipe vous contactera dans les plus brefs délais.
        
        Cordialement,
        L'équipe FK Corporate Intelligence
        """
        
        client_sent = self.send_email(
            to_email=email,
            subject=client_subject,
            body=client_body,
            html_body=client_html
        )
        
        return admin_sent and client_sent

