@app.route('/check-credentials')
def check_credentials():
    """Vérifier les credentials email"""
    
    info = []
    
    # Vérifier la variable d'environnement
    password_from_env = os.environ.get('GMAIL_APP_PASSWORD')
    info.append(f"GMAIL_APP_PASSWORD dans os.environ: {'✅ Défini (' + '*'*10 + password_from_env[-4:] + ')' if password_from_env else '❌ Non défini'}")
    
    # Vérifier dans email_service
    info.append(f"email_service.password: {'✅ Défini (' + '*'*10 + email_service.password[-4:] + ')' if email_service.password else '❌ Non défini'}")
    info.append(f"email_service.simulation_mode: {'⚠️ OUI (mode simulation)' if email_service.simulation_mode else '✅ NON (emails réels)'}")
    
    # Tester la connexion SMTP
    if email_service.password:
        info.append("\n=== TEST SMTP ===")
        try:
            import smtplib
            server = smtplib.SMTP(email_service.smtp_server, email_service.smtp_port, timeout=10)
            server.starttls()
            server.login(email_service.sender_email, email_service.password)
            info.append("✅ Connexion SMTP réussie")
            server.quit()
        except Exception as e:
            info.append(f"❌ Erreur SMTP: {str(e)}")
    
    return "<h1>Vérification des credentials</h1><pre>" + "\n".join(info) + "</pre>"
