@app.route('/super-admin/correct-all-formules-permissions')
@login_required
@super_admin_required
def correct_all_formules_permissions():
    """Corrige toutes les formules pour synchroniser modules et permissions"""
    
    formules = FormuleAbonnement.query.all()
    corrections = []
    
    for formule in formules:
        print(f"🔧 Vérification formule: {formule.nom}")
        
        # MAPPING MODULE → PERMISSIONS
        module_permission_map = {
            'suivi_kri': ['can_manage_kri'],
            'audit_interne': ['can_manage_audit', 'can_confirm_evaluations'],
            'veille_reglementaire': ['can_manage_regulatory'],
            'gestion_processus': ['can_manage_logigram'],
            'analyse_ia': ['can_use_ia_analysis'],
            'reporting_avance': ['can_export_data', 'can_view_reports'],
            'tableaux_bord': ['can_view_dashboard']
        }
        
        # S'assurer que le template existe
        if formule.permissions_template is None:
            formule.permissions_template = {}
        
        # Synchroniser chaque permission
        for module_key, permission_list in module_permission_map.items():
            is_module_active = formule.modules.get(module_key, False)
            
            for permission_key in permission_list:
                if permission_key not in formule.permissions_template:
                    formule.permissions_template[permission_key] = is_module_active
                    corrections.append(f"{formule.nom}: {permission_key} = {is_module_active}")
                elif formule.permissions_template[permission_key] != is_module_active:
                    old_value = formule.permissions_template[permission_key]
                    formule.permissions_template[permission_key] = is_module_active
                    corrections.append(f"{formule.nom}: {permission_key} {old_value} → {is_module_active}")
    
    try:
        db.session.commit()
        flash(f'✅ {len(corrections)} corrections appliquées avec succès', 'success')
        
        # Afficher le détail
        for correction in corrections:
            print(f"  📝 {correction}")
        
    except Exception as e:
        db.session.rollback()
        flash(f'❌ Erreur: {str(e)}', 'error')
    
    return redirect(url_for('super_admin_formules'))



def sync_user_permissions_with_formule(user_id):
    """Synchronise les permissions d'un utilisateur avec sa formule - VERSION CORRIGÉE"""
    user = User.query.get(user_id)
    if not user or not user.client or not user.client.formule:
        return False
    
    formule = user.client.formule
    needs_update = False
    
    # Initialiser les permissions
    if user.permissions is None:
        user.permissions = {}
    
    # Mappage COMPLET module → permission
    module_permission_map = {
        'veille_reglementaire': 'can_manage_regulatory',
        'gestion_processus': 'can_manage_logigram',
        'analyse_ia': 'can_use_ia_analysis',
        'tableaux_bord': 'can_view_dashboard',
        'suivi_kri': 'can_manage_kri',
        'audit_interne': 'can_manage_audit',
        'reporting_avance': 'can_export_data'
    }
    
    # Synchroniser chaque permission
    for module_name, permission in module_permission_map.items():
        is_module_active = formule.modules.get(module_name, False)
        user_has_permission = user.permissions.get(permission, False)
        
        # Correction nécessaire ?
        if user_has_permission != is_module_active:
            user.permissions[permission] = is_module_active
            needs_update = True
            print(f"  🔄 {permission}: {user_has_permission} → {is_module_active}")
    
    if needs_update:
        try:
            user.updated_at = datetime.utcnow()
            db.session.commit()
            print(f"✅ Permissions synchronisées pour {user.username}")
            return True
        except Exception as e:
            db.session.rollback()
            print(f"❌ Erreur: {e}")
            return False
    
    return True


@app.route('/super-admin/correct-modules-permissions')
@login_required
@super_admin_required
def correct_modules_permissions():
    """Correction immédiate des permissions pour les modules problématiques"""
    try:
        # Récupérer toutes les formules
        formules = FormuleAbonnement.query.all()
        total_corrections = 0
        
        for formule in formules:
            print(f"🔧 Correction formule: {formule.nom}")
            
            # Vérifier les modules problématiques
            problem_modules = {
                'veille_reglementaire': ['can_manage_regulatory'],
                'gestion_processus': ['can_manage_logigram'],
                'analyse_ia': ['can_use_ia_analysis']
            }
            
            # S'assurer que permissions_template existe
            if formule.permissions_template is None:
                formule.permissions_template = {}
            
            # Corriger chaque module
            for module_db, permissions in problem_modules.items():
                is_module_active = formule.modules.get(module_db, False)
                
                for permission in permissions:
                    if permission in formule.permissions_template:
                        current_value = formule.permissions_template[permission]
                        
                        # Si incohérence, corriger
                        if current_value != is_module_active:
                            formule.permissions_template[permission] = is_module_active
                            total_corrections += 1
                            print(f"  🔄 {permission}: {current_value} → {is_module_active} (module: {module_db})")
        
        db.session.commit()
        
        # Maintenant synchroniser tous les utilisateurs
        users = User.query.all()
        users_synced = 0
        
        for user in users:
            if user.client and user.client.formule:
                if sync_user_permissions_with_formule(user.id):
                    users_synced += 1
        
        flash(
            f'✅ {total_corrections} permissions corrigées dans les formules. '
            f'{users_synced} utilisateurs synchronisés.', 'success'
        )
        
    except Exception as e:
        db.session.rollback()
        flash(f'❌ Erreur: {str(e)}', 'error')
    
    return redirect(url_for('super_admin_formules'))

