@app.route('/test-gestionnaire-permissions')
@login_required
def test_gestionnaire_permissions():
    """Testez vos permissions de gestionnaire"""
    
    if current_user.role != 'manager':
        return "❌ Pas un gestionnaire"
    
    tests = [
        ('can_create_users', 'Créer utilisateurs'),
        ('can_edit_users', 'Modifier utilisateurs'),
        ('can_deactivate_users', 'Désactiver utilisateurs'),
        ('can_delete_users', 'Supprimer utilisateurs'),
        ('can_view_users_list', 'Voir liste utilisateurs'),
        ('can_manage_permissions', 'Gérer permissions'),
        ('can_manage_users', 'Gérer utilisateurs')
    ]
    
    results = []
    for perm_code, perm_name in tests:
        has_perm = current_user.has_permission(perm_code)
        results.append({
            'permission': perm_code,
            'name': perm_name,
            'has': has_perm,
            'icon': '✅' if has_perm else '❌'
        })
    
    html = f"""
    <html>
    <head><title>Test Permissions Gestionnaire</title></head>
    <body style="padding: 20px; font-family: Arial;">
        <h1>🔧 Test des permissions pour {current_user.username}</h1>
        <p><strong>Rôle:</strong> {current_user.role}</p>
        <p><strong>can_manage_users:</strong> {current_user.can_manage_users}</p>
        
        <h2>Permissions de gestion des utilisateurs :</h2>
        <table border="1" style="border-collapse: collapse; width: 100%;">
            <tr style="background: #f5f5f5;">
                <th style="padding: 10px;">Permission</th>
                <th style="padding: 10px;">Description</th>
                <th style="padding: 10px;">Status</th>
            </tr>
    """
    
    for r in results:
        html += f"""
            <tr>
                <td style="padding: 10px;"><code>{r['permission']}</code></td>
                <td style="padding: 10px;">{r['name']}</td>
                <td style="padding: 10px; text-align: center; color: {'green' if r['has'] else 'red'}">
                    {r['icon']} {r['has']}
                </td>
            </tr>
        """
    
    html += """
        </table>
        
        <div style="margin-top: 30px; padding: 20px; background: #e8f5e8;">
            <h3>Actions :</h3>
            <ul>
                <li><a href="/force-activate-gestionnaire-permissions" style="color: blue;">🔧 FORCER l'activation de toutes les permissions</a></li>
                <li><a href="/gestionnaire/utilisateurs" style="color: blue;">📋 Tester l'accès à la gestion des utilisateurs</a></li>
                <li><a href="/" style="color: blue;">🏠 Retour au dashboard</a></li>
            </ul>
        </div>
    </body>
    </html>
    """
    
    return html
