@app.before_request
def filter_client_data():
    """Filtre automatiquement les données par client"""
    if current_user.is_authenticated and not current_user.role == 'super_admin':
        # Ne pas filtrer les routes publiques ou d'administration
        if request.endpoint and not request.endpoint.startswith(('login', 'logout', 'static', 
                                                                'super_admin', 'client_admin')):
            # Ajouter le filtre client_id aux requêtes
            g.client_id = current_user.client_id

# Dans chaque route qui manipule des données, ajoutez ce filtre :

# ========================
# MIDDLEWARES POUR GESTION DES SESSIONS
# ========================

@app.before_request
def ensure_db_session():
    """S'assure qu'une session DB est active pour la requête"""
    # Démarrer une nouvelle session si nécessaire
    if not db.session.is_active:
        db.session.begin()
    else:
        try:
            # Tester si la session fonctionne
            db.session.execute(text('SELECT 1'))
        except:
            db.session.rollback()
            db.session.close()
            db.session.begin()

@app.after_request
def close_db_session(response):
    """Ferme proprement la session après la requête"""
    try:
        if db.session.is_active:
            db.session.commit()
    except:
        db.session.rollback()
    finally:
        # NE PAS appeler db.session.remove() - cela cause les problèmes
        pass
    return response

@app.teardown_appcontext
def shutdown_session(exception=None):
    """Ferme la session à la fin du contexte de l'application"""
    if exception:
        db.session.rollback()
    # Appeler remove() seulement ici, pas dans after_request
    db.session.remove()
    


