@app.route('/admin/utilisateur/creer', methods=['POST'])
@login_required
def creer_utilisateur():
    if current_user.role != 'admin':
        flash('Accès non autorisé', 'error')
        return redirect(url_for('dashboard'))
    
    username = request.form['username']
    email = request.form['email']
    role = request.form['role']
    department = request.form.get('department')
    password = request.form['password']
    confirm_password = request.form['confirm_password']
    
    if password != confirm_password:
        flash('Les mots de passe ne correspondent pas', 'error')
        return redirect(url_for('liste_utilisateurs'))
    
    if User.query.filter_by(username=username).first():
        flash('Ce nom d\'utilisateur existe déjà', 'error')
        return redirect(url_for('liste_utilisateurs'))
    
    user = User(
        username=username,
        email=email,
        role=role,
        department=department
    )
    user.set_password(password)
    
    db.session.add(user)
    db.session.commit()
    flash('Utilisateur créé avec succès', 'success')
    return redirect(url_for('liste_utilisateurs'))

@app.route('/admin/utilisateur/<int:user_id>/modifier', methods=['POST'])
@login_required
def modifier_utilisateur(user_id):
    if current_user.role != 'admin':
        flash('Accès non autorisé', 'error')
        return redirect(url_for('dashboard'))
    
    user = User.query.get_or_404(user_id)
    user.username = request.form['username']
    user.email = request.form['email']
    user.role = request.form['role']
    user.department = request.form.get('department')
    user.is_active = 'is_active' in request.form
    
    if request.form['password']:
        user.set_password(request.form['password'])
    
    db.session.commit()
    flash('Utilisateur modifié avec succès', 'success')
    return redirect(url_for('liste_utilisateurs'))

@app.route('/admin/utilisateur/<int:user_id>/toggle', methods=['POST'])
@login_required
def toggle_user(user_id):
    if current_user.role != 'admin':
        flash('Accès non autorisé', 'error')
        return redirect(url_for('dashboard'))
    
    user = User.query.get_or_404(user_id)
    if user.id == current_user.id:
        flash('Vous ne pouvez pas désactiver votre propre compte', 'error')
        return redirect(url_for('liste_utilisateurs'))
    
    user.is_active = not user.is_active
    db.session.commit()
    
    status = 'activé' if user.is_active else 'désactivé'
    flash(f'Utilisateur {status} avec succès', 'success')
    return redirect(url_for('liste_utilisateurs'))

