# Route API pour supprimer un logigramme
@app.route('/api/logigramme/<int:activite_id>', methods=['DELETE'])
@login_required
def api_supprimer_logigramme(activite_id):
    activite = ProcessusActivite.query.get_or_404(activite_id)
    
    # Vérifier que l'utilisateur est le propriétaire
    if activite.created_by != current_user.id:
        return jsonify({'error': 'Non autorisé'}), 403
    
    try:
        db.session.delete(activite)
        db.session.commit()
        return jsonify({'message': 'Logigramme supprimé définitivement'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

