@app.route('/logigramme/nouveau', methods=['GET', 'POST'])
@login_required
def nouveau_logigramme():
    from models import Direction, Service
    
    # Récupérer les directions et services
    directions = Direction.query.order_by(Direction.nom).all()
    services = Service.query.order_by(Service.nom).all()
    
    if request.method == 'POST':
        nom = request.form.get('nom')
        description = request.form.get('description')
        direction_id = request.form.get('direction_id')
        service_id = request.form.get('service_id')
        
        if not nom:
            flash('Le nom est obligatoire', 'error')
            return render_template('logigramme/nouveau_logigramme.html', 
                                 directions=directions, services=services)
        
        nouvelle_activite = ProcessusActivite(
            nom=nom,
            description=description,
            direction_id=direction_id if direction_id else None,
            service_id=service_id if service_id else None,
            created_by=current_user.id
        )
        
        try:
            db.session.add(nouvelle_activite)
            db.session.flush()
            
            # ==================== NOTIFICATION ====================
            notification = Notification(
                destinataire_id=current_user.id,
                type_notification=Notification.TYPE_SYSTEME,
                titre=f"Nouveau logigramme créé: {nouvelle_activite.nom}",
                message=f"Le logigramme '{nouvelle_activite.nom}' a été créé avec succès.",
                urgence=Notification.URGENCE_NORMAL,
                entite_type='logigramme',
                entite_id=nouvelle_activite.id,
                donnees_supplementaires={
                    'direction_id': direction_id,
                    'service_id': service_id,
                    'createur': current_user.username
                }
            )
            db.session.add(notification)
            # ======================================================
            
            db.session.commit()
            
            flash('Logigramme créé avec succès!', 'success')
            return redirect(url_for('editer_logigramme', id=nouvelle_activite.id))
            
        except Exception as e:
            db.session.rollback()
            flash('Erreur lors de la création: ' + str(e), 'error')
    
    return render_template('logigramme/nouveau_logigramme.html', 
                         directions=directions, services=services)

# Route pour la liste des logigrammes (corriger le nom)
@app.route('/liste_logigrammes')
@login_required
def liste_logigrammes():
    from datetime import datetime
    
    # VÉRIFICATION FORMULE : vérifier si le client a accès au module "processus"
    if current_user.client and current_user.client.formule:
        formule = current_user.client.formule
        
        # Vérifier si la formule donne accès au module "processus"
        if not formule.can_access_module('processus'):
            # Afficher une page d'upgrade
            try:
                # Récupérer toutes les formules actives
                all_formules = FormuleAbonnement.query.filter(
                    FormuleAbonnement.is_active == True
                ).all()
                
                # Filtrer celles qui ont le module processus
                upgrade_suggestions = []
                for f in all_formules:
                    if f.modules.get('processus', False):
                        upgrade_suggestions.append(f)
                
                # Trier par prix
                upgrade_suggestions.sort(key=lambda x: x.prix_mensuel or 0)
                
                return render_template('errors/formule_restricted.html', 
                                     module_name='Logigrammes et Processus',
                                     current_formule=formule,
                                     upgrade_suggestions=upgrade_suggestions[:3])
                
            except Exception as e:
                print(f"⚠️ Erreur recherche formules upgrade: {e}")
                flash('Ce module n\'est pas inclus dans votre formule actuelle', 'error')
                return redirect(url_for('dashboard'))
    
    # Vérifier la permission de gérer les logigrammes
    if not current_user.has_permission('can_manage_logigram'):
        flash('Accès refusé : permission de gérer les logigrammes requise', 'error')
        return redirect(url_for('dashboard'))
    
    # CORRECTION: Utiliser get_client_filter pour l'isolation multi-tenant
    # Logigrammes actifs
    activites_actives = get_client_filter(ProcessusActivite)\
        .filter_by(is_archived=False)\
        .options(
            db.joinedload(ProcessusActivite.direction),
            db.joinedload(ProcessusActivite.service),
            db.joinedload(ProcessusActivite.elements),
            db.joinedload(ProcessusActivite.liens)
        ).order_by(ProcessusActivite.created_at.desc()).all()

    # Logigrammes archivés (juste pour le compteur)
    activites_archivees = get_client_filter(ProcessusActivite)\
        .filter_by(is_archived=True)\
        .all()

    # Debug: vérifier l'isolation
    print(f"🔍 LISTE LOGIGRAMMES - Utilisateur: {current_user.username}")
    print(f"   Rôle: {current_user.role}, Client ID: {current_user.client_id}")
    print(f"   Logigrammes actifs: {len(activites_actives)}")
    print(f"   Logigrammes archivés: {len(activites_archivees)}")
    
    # Vérifier l'accès pour chaque activité
    for activite in activites_actives:
        if not check_client_access(activite):
            print(f"⚠️ ALERTE: L'utilisateur n'a pas accès au logigramme {activite.id}")

    # Calcul des statistiques
    total_elements = sum(len(activite.elements) for activite in activites_actives)
    total_liens = sum(len(activite.liens) for activite in activites_actives)

    # Directions pour les filtres - CORRECTION: utiliser get_client_filter
    directions = get_client_filter(Direction).order_by(Direction.nom).all()
    services = get_client_filter(Service).order_by(Service.nom).all()

    # Log pour debug
    print(f"📊 Statistiques logigrammes:")
    print(f"   - Activités actives: {len(activites_actives)}")
    print(f"   - Activités archivées: {len(activites_archivees)}")
    print(f"   - Total éléments: {total_elements}")
    print(f"   - Total liens: {total_liens}")
    print(f"   - Directions disponibles: {len(directions)}")
    print(f"   - Services disponibles: {len(services)}")

    # Calculer des statistiques supplémentaires
    stats = {
        'total_actifs': len(activites_actives),
        'total_archives': len(activites_archivees),
        'total_elements': total_elements,
        'total_liens': total_liens,
        'moyenne_elements': round(total_elements / max(len(activites_actives), 1), 1),
        'moyenne_liens': round(total_liens / max(len(activites_actives), 1), 1)
    }

    return render_template('logigramme/liste_logigrammes.html', 
                         activites_actives=activites_actives,
                         activites_archivees=activites_archivees,
                         total_elements=total_elements,
                         total_liens=total_liens,
                         directions=directions,
                         services=services,
                         stats=stats,
                         now=datetime.now(),
                         current_user=current_user)


@app.route('/api/logigramme/<int:activite_id>', methods=['PUT'])
@csrf.exempt  # <-- AJOUTER CETTE LIGNE
@login_required
def api_modifier_logigramme(activite_id):
    """API pour modifier les informations d'un logigramme"""
    activite = ProcessusActivite.query.get_or_404(activite_id)
    
    # Vérifier que l'utilisateur est le propriétaire
    if activite.created_by != current_user.id:
        return jsonify({'error': 'Non autorisé'}), 403
    
    data = request.get_json()
    
    try:
        # Mettre à jour les champs
        if 'nom' in data:
            activite.nom = data['nom']
        if 'description' in data:
            activite.description = data['description']
        if 'direction_id' in data:
            activite.direction_id = data['direction_id'] if data['direction_id'] else None
        if 'service_id' in data:
            activite.service_id = data['service_id'] if data['service_id'] else None
        
        activite.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Logigramme modifié avec succès',
            'logigramme': {
                'id': activite.id,
                'nom': activite.nom,
                'description': activite.description,
                'direction_id': activite.direction_id,
                'service_id': activite.service_id
            }
        })
        
    except Exception as e:
        db.session.rollback()
        print(f"Erreur modification logigramme: {e}")
        return jsonify({
            'success': False,
            'message': 'Erreur lors de la modification du logigramme: ' + str(e)
        }), 500

